mapper.select:
SELECT count(*) FROM work
WHERE state IN ('INDEXED','NOTIFIED') AND pending_finder_run IS NOT NULL
  AND placed_release IS DISTINCT FROM #{releaseKey}

mapper.update:
UPDATE xr_release SET state = 'PREPARING', switch_started = now(), switched_at = NULL, keys_total = NULL,
  keys_lost = NULL, note = #{note}, switch_gen = switch_gen + 1
WHERE key = #{key}

UPDATE work SET current_finder_run = #{finderRunId}, names_doc_sha = #{docSha}, names_text_level = #{textLevel},
  state = 'NAMES_FOUND', modified = now()
WHERE id = #{workId}

mapper.select:
SELECT id FROM work WHERE current_finder_run IS NOT NULL AND id > #{afterId}
 AND source_id = #{sourceId}
 AND id = ANY(#{workIds, typeHandler=org.catalogueoflife.garrulus.store.type.LongListTypeHandler})
  AND year >= #{yearFrom} 
  AND year <= #{yearTo} 
ORDER BY id LIMIT #{limit}

SELECT w.id FROM work w
WHERE w.state IN ('INDEXED','NOTIFIED') AND w.id > #{afterId}
  AND EXISTS (SELECT 1 FROM work_name wn JOIN name_ubiquity u ON u.name_string_id = wn.name_string_id
              WHERE wn.work_id = w.id
                AND abs(least(1.0, u.share / #{full}) - least(1.0, coalesce(u.scored_share, 0) / #{full})) > #{threshold})
ORDER BY w.id LIMIT #{limit}

mapper.update:
UPDATE work SET codes = #{codes, typeHandler=org.catalogueoflife.garrulus.store.type.StringArrayTypeHandler},
  taxgroups = #{taxgroups, typeHandler=org.catalogueoflife.garrulus.store.type.StringArrayTypeHandler},
  has_acts = #{hasActs}, modified = now()
WHERE id = #{workId}
  AND (codes IS DISTINCT FROM #{codes, typeHandler=org.catalogueoflife.garrulus.store.type.StringArrayTypeHandler}
    OR taxgroups IS DISTINCT FROM #{taxgroups, typeHandler=org.catalogueoflife.garrulus.store.type.StringArrayTypeHandler}
    OR has_acts IS DISTINCT FROM #{hasActs})
